from __future__ import absolute_import

from taf.selenium.gnb.oam.coam.vdu.pages import v25R1, ParameterEditorPageViewPanel, v22R2


class Configuration(v25R1.Configuration):
    def __init__(self, driver, version):
        if not self._instance_dict:
            super(Configuration, self).__init__(driver, version)
            self._instance_dict.update({"Parameter Editor": ParameterEditorPageV25R2(driver, version)})


class ParameterEditorPageV25R2(v22R2.ParameterEditorPageV22R2):
    def __init__(self, driver, version):
        super(ParameterEditorPageV25R2, self).__init__(driver, version)
        self._view_panel = ParameterEditorPageViewPanelV25R2(driver, version)


class ParameterEditorPageViewPanelV25R2(ParameterEditorPageViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(ParameterEditorPageViewPanelV25R2, self).__init__(driver, version)

    def _input_abbreviation(self, abbr, timeout):
        """
        Filter the parameter using given abbreviation

        :param abbr: str, abbreviation
        :param timeout: int, timeout for the element be available to click
        """
        self.click_enabled_element(self.locator.ABBREVIATION_INPUT_ID, timeout=5)
        self.click_enabled_element(self.locator.SELECT_PARAMETER_TABLE_XPATH)
        if abbr:
            self.insert_text_to_enable_element(self.locator.ABBREVIATION_INPUT_ID, abbr, timeout)

    def _find_and_parse_all_parameter_details(self):
        """
            This keyword find and parse all the parameters details from parameter details panel and convert them dictionary

        :return: dict, returns dictionary of details of the parameter
        """
        parameter_details = self._get_parameter_basic_info()
        details_elements = self._driver.find_elements_by_xpath(self.locator.PARAMETER_DETAILS_DATA_ROW_XPATH)
        for info in range(1, len(details_elements) + 1):
            key = self._driver.find_element_by_xpath(
                (self.locator.PARAMETER_DETAILS_DATA_ROW_XPATH_KEY.format(info))).text
            value = self._driver.find_element_by_xpath(
                self.locator.PARAMETER_DETAILS_DATA_ROW_XPATH_VALUE.format(info)).text
            parameter_details[key] = value
        parameter_details.update(self._get_parameter_additional_info())
        return parameter_details

    def _get_parameter_basic_info(self):
        """
        This keyword find and parse basic details (Name and  Abbreviated name) of the parameters details from parameter
        details panel and convert them to dictionary

        :return: dict, returns dictionary of basic detail of the parameter
        """

        parameter_names = {}
        self.wait_for_visibility(self.locator.PARAMETER_DETAILS_TITEL_XPATH)
        parameter_names["Full parameter name"] = self._driver.find_element_by_xpath(
            self.locator.FULL_PARAMETER_NAME).text
        parameter_names["Abbreviated parameter name"] = self._driver.find_element_by_xpath(
            self.locator.ABBREVIATED_PARAMETER_NAME).text
        return parameter_names

    def _get_parameter_additional_info(self):
        """
            This keyword find and parse additional  details of the parameters details form parameter details
            panel and convert them to dictionary

        :return: dict, returns dictionary of additional detail of the parameter
        """
        additional_info = {}
        additional_items = self._driver.find_elements_by_xpath(self.locator.PARAMETER_ADDITIONAL_DETAILS)
        for index in range(2, len(additional_items) + 1):
            key = self._driver.find_element_by_xpath(
                (self.locator.PARAMETER_ADDITIONAL_DETAILS_XPATH.format(index, 'a'))).text
            info_value_xpath = self.locator.PARAMETER_ADDITIONAL_DETAILS_XPATH_VALUE.format(index)
            info = self._driver.find_element_by_xpath(info_value_xpath).text
            additional_info[key] = info
        return additional_info
